begin;
-- Departments
on conflict (code) do nothing;

-- Semesters (8 per department)
select d.id, s.n from public.departments d
cross join (values (1),(2),(3),(4),(5),(6),(7),(8)) as s(n)
on conflict (department_id, number) do nothing;

-- Curriculum versions
select d.id, 'official', true, 138 from public.departments d where d.code = 'IS'
union all
select d.id, 'official', true, 157 from public.departments d where d.code = 'SE'
union all
select d.id, 'official', true, 120 from public.departments d where d.code = 'DS'
on conflict (department_id, version) do nothing;

-- Courses
-- IS
on conflict (curriculum_version_id, code) do nothing;

-- SE
on conflict (curriculum_version_id, code) do nothing;

-- DS
on conflict (curriculum_version_id, code) do nothing;

-- Elective requirements
select d.id, v.semester, v.required_credits from (values
  ('IS', 5, 10),
  ('IS', 7, 9),
  ('IS', 8, 9),
  ('SE', 5, 10),
  ('SE', 6, 10),
  ('SE', 8, 8),
  ('DS', 5, 4),
  ('DS', 6, 2),
  ('DS', 7, 4),
  ('DS', 8, 2)
) as v(code, semester, required_credits)
join public.departments d on d.code = v.code
on conflict (department_id, semester) do update set required_credits = excluded.required_credits, updated_at = now();

-- Grading scale + grade points
select s.id, v.label, v.gp, v.min_pct, v.counts from public.grading_scales s cross join (values
  ('A+', 4, 90, true),
  ('A', 4, 80, true),
  ('A-', 3.7, 75, true),
  ('B+', 3.3, 70, true),
  ('B', 3, 65, true),
  ('B-', 2.7, 60, true),
  ('C+', 2.3, 55, true),
  ('C', 2, 50, true),
  ('C-', 1.7, 45, true),
  ('D+', 1.3, 40, true),
  ('D', 1, 30, true),
  ('E', 0, 0, false)
) as v(label, gp, min_pct, counts) where s.name='Official University Scale'
on conflict (scale_id, label) do nothing;


commit;
